import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { stepButton, stepDescription, stepTitle, t } from '../../common/text';
import { fullJourney, own } from '../state';
import { actionFor, run } from '../actions';
import Ring from './Ring';
import useStyles from '../styles';
useStyles();
import StepRow from './StepRow';

/*
 * 🚨 Its own chunk: the launcher's panel and the widget's body.
 *
 * Only a member mid-journey ever draws either, and that is a sliver of the
 * people loading any page. Everyone else — guests, regulars, graduates — gets
 * a forum.js without the step rows, the actions or the panel at all.
 */

/** The first step neither done nor skipped. */
export function nextStep(journey) {
  return journey?.steps.find(s => !s.completedAt && !s.skippedAt) ?? null;
}

/** The open launcher: the next step and its button, then every step. */
export class Panel extends Component {
  view() {
    const journey = fullJourney();
    if (!journey) return m(LoadingIndicator, {
      size: "small"
    });
    const next = nextStep(journey);
    const close = () => document.body.click();
    return m("div", {
      className: "OnrampPanel"
    }, m("header", {
      className: "OnrampPanel-head"
    }, m(Ring, {
      done: journey.done + journey.skipped,
      total: journey.total,
      size: 44,
      label: `${journey.done}/${journey.total}`
    }), m("div", null, m("strong", null, t('forum.launcher.title')), m("div", {
      className: "OnrampPanel-sub"
    }, t('forum.launcher.sub', {
      count: journey.total - journey.done - journey.skipped
    })))), next ? m("section", {
      className: "OnrampPanel-next"
    }, m("div", {
      className: "OnrampPanel-nextLabel"
    }, t('forum.launcher.next')), m("div", {
      className: "OnrampPanel-nextTitle"
    }, stepTitle(next)), m("p", {
      className: "OnrampPanel-nextText"
    }, stepDescription(next)), actionFor(next) ? m(Button, {
      className: "Button Button--primary Button--block",
      onclick: () => run(next, close)
    }, stepButton(next)) : null) : null, m("ol", {
      className: "OnrampPanel-steps"
    }, journey.steps.map((step, i) => m(StepRow, {
      step: step,
      index: i,
      compact: true
    }))), m(Link, {
      className: "OnrampPanel-all",
      href: app.route('onramp'),
      onclick: close
    }, t('forum.launcher.see_all')));
  }
}

/** "Your journey" in a sidebar: the ring, the next step and its button. */
export class WidgetBody extends Component {
  view() {
    const journey = own();
    if (!journey) return null;
    const next = nextStep(journey);
    return m("div", {
      className: "OnrampWidget"
    }, m("div", {
      className: "OnrampWidget-head"
    }, m(Ring, {
      done: journey.done + journey.skipped,
      total: journey.total,
      size: 40,
      label: `${journey.done}/${journey.total}`
    }), m("div", null, m("h4", {
      className: "OnrampWidget-title"
    }, t('forum.widget.title')), m("div", {
      className: "OnrampWidget-sub"
    }, t('forum.launcher.sub', {
      count: journey.total - journey.done - journey.skipped
    })))), next ? m("div", {
      className: "OnrampWidget-next"
    }, m("div", {
      className: "OnrampWidget-nextTitle"
    }, stepTitle(next)), actionFor(next) ? m(Button, {
      className: "Button Button--primary Button--block",
      onclick: () => run(next)
    }, stepButton(next)) : null) : null, m(Link, {
      className: "OnrampWidget-link",
      href: app.route('onramp')
    }, t('forum.launcher.see_all')));
  }
}
flarum.reg.add('ernestdefoe-onramp', 'forum/components/Journey', { nextStep: nextStep,Panel: Panel,WidgetBody: WidgetBody, });